475	        SOURCE_ROOT / "utilities" / "RunOspreyJob.m",
476	    ]
477	    missing = [
478	        str(path.relative_to(TASK_DIR)) for path in entrypoints if not path.is_file()
479	    ]
480	    if missing:
481	        raise RuntimeError(
482	            "missing supplied project entrypoints: " + ", ".join(missing)
483	        )
484	
